r(err)\n  },\n  onOpen: () => {\n    $message.success(\'WebSocket 连接成功\')\n  },\n  onClose: () => {\n    if (!isReconnecting.value) {\n      $message.warning(\'WebSocket 连接已关闭\')\n    }\n  }\n})\n\n// 处理 WebSocket 消息\nconst handleWebSocketMessage = (event) => {\n  try {\n    const data = JSON.parse(event.data)\n    \n    // 忽略心跳消息\n    if (data.type === \'pong\') {\n      return\n    }\n    \n    // 提取日志字段\n    const logEntry = {\n      timestamp: data.timestamp || Date.now(),\n      level: data.level || \'INFO\',\n      message: data.message || event.data\n    }\n    \n    logs.value.push(logEntry)\n    \n    // 如果启用了自动滚动，添加到终端\n    if (autoScroll.value && terminalRef.value) {\n      terminalRef.value.addLog(logEntry)\n    }\n  } catch (err) {\n    // 如果不是 JSON，当作纯文本处理\n    const logEntry = {\n      timestamp: Date.now(),\n      level: \'INFO\',\n      message: event.data\n    }\n    \n    logs.value.push(logEntry)\n    \n    if (autoScroll.value && terminalRef.value) {\n      terminalRef.value.addLog(logEntry)\n    }\n  }\n}\n\n// 处理 WebSocket 错误\nconst handleWebSocketError = (err) => {\n  console.error(\'WebSocket error:\', err)\n  $message.error(`WebSocket 连接失败: ${err.message || \'未知错误\'}`)\n}\n\n// 监听错误状态\nwatch(wsError, (newError) => {\n  if (newError) {\n    $message.error(`连接错误: ${newError.message}`)\n  }\n})\n\n// 过滤日志\nconst filteredLogs = computed(() => {\n  let result = logs.value\n  \n  // 根据日志级别过滤\n  if (selectedLevels.value.length > 0) {\n    result = result.filter(log => selectedLevels.value.includes(log.level))\n  }\n  \n  // 根据关键词过滤\n  if (filterText.value.trim()) {\n    const keyword = filterText.value.toLowerCase()\n    result = result.filter(log => \n      log.message.toLowerCase().includes(keyword)\n    )\n  }\n  \n  return result\n})\n\n// 日志类型切换\nconst handleLogTypeChange = (newType) => {\n  // 断开当前连接\n  disconnect()\n  \n  // 清空日志\n  logs.value = []\n  if (terminalRef.value) {\n    terminalRef.value.clearLogs()\n  }\n  \n  // 更新日志类型\n  selectedLogType.value = newType\n  \n  // 重新建立连接（在下一个 tick 中，确保 URL 已更新）\n  setTimeout(() => {\n    const newUrl = buildWebSocketUrl(newType)\n    connect()\n  }, 100)\n}\n\n// 日志级别变化\nconst handleLevelsChange = (levels) => {\n  selectedLevels.value = levels\n  updateTerminal()\n}\n\n// 过滤关键词变化\nconst handleFilterChange = (text) => {\n  filterText.value = text\n  updateTerminal()\n}\n\n// 更新终端显示\nconst updateTerminal = () => {\n  if (!terminalRef.value) return\n  \n  // 清空终端\n  terminalRef.value.clearLogs()\n  \n  // 添加过滤后的日志\n  filteredLogs.value.forEach(log => {\n    terminalRef.value.addLog(log)\n  })\n}\n\n// 清空日志\nconst handleClear = () => {\n  logs.value = []\n  if (terminalRef.value) {\n    terminalRef.value.clearLogs()\n  }\n  $message.success(\'日志已清空\')\n}\n\n// 导出日志\nconst handleExport = () => {\n  if (filteredLogs.value.length === 0) {\n    $message.warning(\'没有可导出的日志\')\n    return\n  }\n  \n  // 生成日志内容\n  const logContent = filteredLogs.value.map(log => {\n    const timestamp = formatTimestamp(log.timestamp)\n    return `[${timestamp}] [${log.level}] ${log.message}`\n  }).join(\'\\n\')\n  \n  // 创建 Blob 对象\n  const blob = new Blob([logContent], { type: \'text/plain;charset=utf-8\' })\n  \n  // 创建下载链接\n  const url = URL.createObjectURL(blob)\n  const link = document.createElement(\'a\')\n  link.href = url\n  link.download = `logs_${selectedLogType.value}_${Date.now()}.log`\n  \n  // 触发下载\n  document.body.appendChild(link)\n  link.click()\n  \n  // 清理\n  document.body.removeChild(link)\n  URL.revokeObjectURL(url)\n  \n  $message.success(`已导出 ${filteredLogs.value.length} 条日志`)\n}\n\n// 格式化时间戳\nconst formatTimestamp = (timestamp) => {\n  const date = new Date(timestamp)\n  const year = date.getFullYear()\n  const month = String(date.getMonth() + 1).padStart(2, \'0\')\n  const day = String(date.getDate()).padStart(2, \'0\')\n  const hours = String(date.getHours()).padStart(2, \'0\')\n  const minutes = String(date.getMinutes()).padStart(2, \'0\')\n  const seconds = String(date.getSeconds()).padStart(2, \'0\')\n  const milliseconds = String(date.getMilliseconds()).padStart(3, \'0\')\n  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`\n}\n\n// 切换自动滚动\nconst handleToggleAutoScroll = (value) => {\n  autoScroll.value = value\n}\n\n// 组件挂载时建立连接\nonMounted(() => {\n  connect()\n})\n</script>\n\n<template>\n  <div class=\"realtime-log-container\">\n    <!-- 工具栏 -->\n    <div class=\"toolbar-wrapper\">\n      <LogToolbar\n        :log-types=\"logTypes\"\n        :selected-log-type=\"selectedLogType\"\n        :selected-levels=\"selectedLevels\"\n        :filter-text=\"filterText\"\n        :auto-scroll=\"autoScroll\"\n        :is-connected=\"isConnected\"\n        :log-count=\"filteredLogs.length\"\n        @update:logType=\"handleLogTypeChange\"\n        @update:levels=\"handleLevelsChange\"\n        @update:filter=\"handleFilterChange\"\n        @clear=\"handleClear\"\n        @export=\"handleExport\"\n        @toggle:autoScroll=\"handleToggleAutoScroll\"\n      />\n    </div>\n    \n    <!-- 日志终端 -->\n    <div class=\"terminal-wrapper\">\n      <LogTerminal\n        ref=\"terminalRef\"\n        :max-logs=\"10000\"\n        :auto-scroll=\"autoScroll\"\n      />\n    </div>\n    \n    <!-- 重连提示 -->\n    <div v-if=\"isReconnecting\" class=\"reconnecting-banner\">\n      <n-text type=\"warning\">\n        连接断开，正在尝试重新连接...\n      </n-text>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.realtime-log-container {\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  background-color: #fff;\n  border-radius: 4px;\n  overflow: hidden;\n}\n\n.toolbar-wrapper {\n  padding: 16px;\n  border-bottom: 1px solid #e5e7eb;\n  background-color: #fff;\n  flex-shrink: 0;\n}\n\n.terminal-wrapper {\n  flex: 1;\n  overflow: hidden;\n  background-color: #1e1e1e;\n}\n\n.reconnecting-banner {\n  position: fixed;\n  top: 0;\n  left: 50%;\n  transform: translateX(-50%);\n  background-color: #fef3cd;\n  border: 1px solid #ffc107;\n  padding: 8px 16px;\n  border-radius: 0 0 4px 4px;\n  z-index: 9999;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\n}\n</style>\n','/* Analyzed bindings: {\n  \"ref\": \"setup-const\",\n  \"computed\": \"setup-const\",\n  \"onMounted\": \"setup-const\",\n  \"watch\": \"setup-const\",\n  \"useWebSocket\": \"setup-maybe-ref\",\n  \"useUserStore\": \"setup-maybe-ref\",\n  \"LogTerminal\": \"setup-const\",\n  \"LogToolbar\": \"setup-const\",\n  \"userStore\": \"setup-maybe-ref\",\n  \"terminalRef\": \"setup-ref\",\n  \"logs\": \"setup-ref\",\n  \"selectedLogType\": \"setup-ref\",\n  \"selectedLevels\": \"setup-ref\",\n  \"filterText\": \"setup-ref\",\n  \"autoScroll\": \"setup-ref\",\n  \"logTypes\": \"setup-const\",\n  \"buildWebSocketUrl\": \"setup-const\",\n  \"wsUrl\": \"setup-ref\",\n  \"isConnected\": \"setup-maybe-ref\",\n  \"isReconnecting\": \"setup-maybe-ref\",\n  \"wsError\": \"setup-maybe-ref\",\n  \"connect\": \"setup-maybe-ref\",\n  \"disconnect\": \"setup-maybe-ref\",\n  \"handleWebSocketMessage\": \"setup-const\",\n  \"handleWebSocketError\": \"setup-const\",\n  \"filteredLogs\": \"setup-ref\",\n  \"handleLogTypeChange\": \"setup-const\",\n  \"handleLevelsChange\": \"setup-const\",\n  \"handleFilterChange\": \"setup-const\",\n  \"updateTerminal\": \"setup-const\",\n  \"handleClear\": \"setup-const\",\n  \"handleExport\": \"setup-const\",\n  \"formatTimestamp\": \"setup-const\",\n  \"handleToggleAutoScroll\": \"setup-const\"\n} */\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\