l\n  link.download = `logs_${selectedLogType.value}_${Date.now()}.log`\n  \n  // 触发下载\n  document.body.appendChild(link)\n  link.click()\n  \n  // 清理\n  document.body.removeChild(link)\n  URL.revokeObjectURL(url)\n  \n  $message.success(`已导出 ${filteredLogs.value.length} 条日志`)\n}\n\n// 格式化时间戳\nconst formatTimestamp = (timestamp) => {\n  const date = new Date(timestamp)\n  const year = date.getFullYear()\n  const month = String(date.getMonth() + 1).padStart(2, \'0\')\n  const day = String(date.getDate()).padStart(2, \'0\')\n  const hours = String(date.getHours()).padStart(2, \'0\')\n  const minutes = String(date.getMinutes()).padStart(2, \'0\')\n  const seconds = String(date.getSeconds()).padStart(2, \'0\')\n  const milliseconds = String(date.getMilliseconds()).padStart(3, \'0\')\n  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`\n}\n\n// 切换自动滚动\nconst handleToggleAutoScroll = (value) => {\n  autoScroll.value = value\n}\n\n// 组件挂载时建立连接\nonMounted(() => {\n  connect()\n})\n\nreturn (_ctx, _cache) => {\n  const _component_n_text = _resolveComponent(\"n-text\")\n\n  return (_openBlock(), _createElementBlock(\"div\", _hoisted_1, [\n    _createCommentVNode(\" 工具栏 \"),\n    _createElementVNode(\"div\", _hoisted_2, [\n      _createVNode(LogToolbar, {\n        \"log-types\": logTypes,\n        \"selected-log-type\": selectedLogType.value,\n        \"selected-levels\": selectedLevels.value,\n        \"filter-text\": filterText.value,\n        \"auto-scroll\": autoScroll.value,\n        \"is-connected\": _unref(isConnected),\n        \"log-count\": filteredLogs.value.length,\n        \"onUpdate:logType\": handleLogTypeChange,\n        \"onUpdate:levels\": handleLevelsChange,\n        \"onUpdate:filter\": handleFilterChange,\n        onClear: handleClear,\n        onExport: handleExport,\n        \"onToggle:autoScroll\": handleToggleAutoScroll\n      }, null, 8 /* PROPS */, [\"selected-log-type\", \"selected-levels\", \"filter-text\", \"auto-scrol